import numpy as np
from scipy.optimize import minimize

def f(params):
    x, y, z = params
    if x <= 0 or y <= 0 or z <= 0:
        return 1e10
    return ((2*x**2 + 1)*(2*y**2 + 1)*(2*z**2 + 1)) / (x*y + y*z + z*x)

res = minimize(f, [0.5, 0.5, 0.5], bounds=[(1e-6, None), (1e-6, None), (1e-6, None)])
print(f"Minimum value: {res.fun}")
print(f"Optimal (x, y, z): {res.x}")

